text:
/* Shared Compose structure. Appearance colors come from the active palette. */
.compose-page {
  --recipients-bg: var(--background);
  --recipients-surface: var(--card);
  --recipients-card: var(--card);
  --recipients-border: var(--border);
  --recipients-text: var(--foreground);
  --recipients-text-muted: var(--body);
  --recipients-label: var(--body);
  --recipients-accent: var(--accent);
  --recipients-accent-2: var(--accent2);
  --recipients-track: var(--surface);
  --recipients-pill-bg: var(--warning-soft);
  --recipients-pill-border: color-mix(
    in srgb,
    var(--queued) 45%,
    var(--border)
  );
  --recipients-pill-text: var(--warning);
}
.compose-hero h1 {
  font-size: 30px;
  line-height: 1.25;
  letter-spacing: -1px;
  font-weight: 650;
}
.compose-hero p {
  margin-top: 7px;
  color: var(--body);
  font-size: 14px;
}
.compose-page .recipient-card {
  padding: 16px;
  border-radius: 16px;
}
.compose-page .recipient-header .text-\[17px\] {
  font-size: 15px;
}
.compose-page .recipient-summary {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  min-width: 0;
}
.compose-page .recipient-email {
  display: block;
  margin-top: 3px;
  color: var(--recipients-text-muted);
  font-size: 13px;
  overflow-wrap: anywhere;
}
.compose-page .recipient-role-badge {
  max-width: 180px;
  padding: 5px 10px;
  border-radius: 999px;
  background: var(--surface);
  color: var(--body);
  font-size: 12px;
  font-weight: 500;
  overflow-wrap: anywhere;
}
.compose-page .recipient-details {
  font-size: 12px;
  row-gap: 6px;
}
.compose-page .send-queue-panel > [aria-live="polite"]:empty {
  min-height: 0;
  margin-block: 0;
}
@media (max-width: 767px) {
  .compose-hero h1 {
    font-size: 28px;
  }
}
@media (max-width: 600px) {
  .compose-page .recipient-summary {
    grid-template-columns: 18px minmax(0, 1fr);
    gap: 8px 12px;
  }
  .compose-page .recipient-role-badge {
    grid-column: 2;
    justify-self: start;
    max-width: 100%;
  }
}

/* Keep draft selection yellow against Lavender's light cards. */
html[data-theme="light"][data-appearance="purple"] .draft-progress {
  --queued: var(--color-globals-queued-39);
}
